SELECT COUNT(*) AS orphan_candidate_roles FROM d1_person_candidate_roles r LEFT JOIN d1_people p ON p.id=r.person_id WHERE p.id IS NULL;
SELECT COUNT(*) AS orphan_legislator_roles FROM d1_person_legislator_roles r LEFT JOIN d1_people p ON p.id=r.person_id WHERE p.id IS NULL;
SELECT COUNT(*) AS orphan_contributions FROM d1_candidate_contributions c LEFT JOIN d1_people p ON p.id=c.person_id WHERE c.person_id IS NOT NULL AND p.id IS NULL;
SELECT COUNT(*) AS orphan_primary_results FROM d1_candidate_primary_results r LEFT JOIN d1_people p ON p.id=r.person_id WHERE p.id IS NULL;
SELECT COUNT(*) AS orphan_article_people FROM d1_article_people a LEFT JOIN d1_people p ON p.id=a.person_id WHERE p.id IS NULL;
